import { Alert } from 'react-native';

// react-native-web's Alert.alert is a no-op, and the iframe preview's Alert
// component isn't visible. Route both Alert.alert and the global alert()
// through window.alert so either API works on web.
Alert.alert = (title?: string, message?: string) => {
  window.alert([title, message].filter(Boolean).join('\n\n'));
};

import { SymbolView, SymbolViewProps, SymbolWeight } from "expo-symbols";
import { Pressable, StyleProp, ViewStyle } from "react-native";

export function IconSymbol({
  ios_icon_name,
  android_material_icon_name,
  size = 24,
  color,
  style,
  weight = "regular",
  onPress,
  testID,
  accessibilityLabel,
}: {
  ios_icon_name: SymbolViewProps["name"];
  android_material_icon_name: any;
  size?: number;
  color: string;
  style?: StyleProp<ViewStyle>;
  weight?: SymbolWeight;
  onPress?: () => void;
  testID?: string;
  accessibilityLabel?: string;
}) {
  const symbol = (
    <SymbolView
      weight={weight}
      tintColor={color}
      resizeMode="scaleAspectFit"
      name={ios_icon_name}
      style={[{ width: size, height: size }, style]}
    />
  );

  if (onPress) {
    return (
      <Pressable
        onPress={onPress}
        testID={testID}
        accessibilityLabel={accessibilityLabel}
        accessibilityRole="button"
        hitSlop={8}
        style={{ width: size, height: size }}
      >
        {symbol}
      </Pressable>
    );
  }

  return symbol;
}
